import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int q = nextInt();
        long shortMax = 0, longMax = 0;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long kind = nextLong(), a = nextLong(), b = nextLong();
            // Compare short side with short side and long side with long side.
            long s = Math.min(a, b), l = Math.max(a, b);
            if (kind == 0) {
                shortMax = Math.max(shortMax, s);
                longMax = Math.max(longMax, l);
            } else {
                out.append(shortMax <= s && longMax <= l ? "1\n" : "0\n");
            }
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := nextInt()
	shortMax, longMax := 0, 0
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		kind, a, b := nextInt(), nextInt(), nextInt()
		// Compare short side with short side and long side with long side.
		s, l := min(a, b), max(a, b)
		if kind == 0 {
			shortMax = max(shortMax, s)
			longMax = max(longMax, l)
		} else if shortMax <= s && longMax <= l {
			w.WriteString("1\n")
		} else {
			w.WriteString("0\n")
		}
	}
}
